nodes = {"gpu-a01": 8, "gpu-a02": 8, "gpu-b01": 8}
pods = [("gpu-a01", 4), ("gpu-a01", 4), ("gpu-a02", 2), ("gpu-b01", 1)]

used = {n: 0 for n in nodes}
for node, gpus in pods:
    used[node] += gpus

for n, total in nodes.items():
    print(f"{n}: {total - used[n]}/{total} 남음")
print("8장 한 노드에 들어갈 곳:", [n for n in nodes if nodes[n] - used[n] >= 8] or "없음")

# 출력
# gpu-a01: 0/8 남음
# gpu-a02: 6/8 남음
# gpu-b01: 7/8 남음
# 8장 한 노드에 들어갈 곳: 없음
